import { Buffer } from "node:buffer";

/**
 * Genuine, complete, and valid minimal OOXML workbook (.xlsx).
 * Generated with openpyxl containing full Open Packaging Conventions parts,
 * valid CRC32 checksums, workbook relationships and sheet XML.
 */
export const GENUINE_MINIMAL_XLSX_BASE64 =
  "";

export function getGenuineMinimalXlsxBuffer(): Buffer {
  return Buffer.from(GENUINE_MINIMAL_XLSX_BASE64, "base64");
}

export function getGenuineMinimalXlsxArrayBuffer(): ArrayBuffer {
  const buf = Buffer.from(GENUINE_MINIMAL_XLSX_BASE64, "base64");
  const ab = new ArrayBuffer(buf.byteLength);
  new Uint8Array(ab).set(buf);
  return ab;
}
